import { createHash, randomBytes } from "node:crypto";
import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseAdminRest, supabaseRest } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

type HouseholdRow = { id: string; owner_id: string; name: string };
type InviteRow = { id: string; household_id: string; email: string; token_hash: string; can_add_memories: boolean; expires_at: string; accepted_at?: string | null };

function hashToken(token: string) {
  return createHash("sha256").update(token).digest("hex");
}

function apiError(cause: unknown, fallback: string) {
  const message = cause instanceof Error ? cause.message : fallback;
  const status = message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : /forbidden|owner/i.test(message) ? 403 : 400;
  return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Sign in to manage household invitations." : message }, { status });
}

export async function POST(request: Request) {
  try {
    const { token, user } = await requireStorySession();
    const body = await request.json() as { householdId?: string; email?: string; canAddMemories?: boolean };
    const email = body.email?.trim().toLowerCase() ?? "";
    if (!body.householdId || !/^[0-9a-f-]{36}$/i.test(body.householdId)) throw new Error("Invalid household id.");
    if (!/^\S+@\S+\.\S+$/.test(email) || email.length > 254) throw new Error("Enter a valid household member email.");
    if (user.email?.toLowerCase() === email) throw new Error("You are already the household owner.");
    const household = (await supabaseRest<HouseholdRow[]>(`households?select=id,owner_id,name&id=eq.${encodeURIComponent(body.householdId)}&owner_id=eq.${encodeURIComponent(user.id)}&limit=1`, token))[0];
    if (!household) throw new Error("Only the household owner can invite members.");

    const rawToken = randomBytes(32).toString("base64url");
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
    const rows = await supabaseRest<Array<{ id: string }>>("household_invites?select=id", token, {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify({ household_id: household.id, created_by: user.id, email, token_hash: hashToken(rawToken), can_add_memories: body.canAddMemories !== false, expires_at: expiresAt }),
    });
    const origin = new URL(request.url).origin;
    return NextResponse.json({ inviteId: rows[0]?.id, inviteUrl: `${origin}/products/petlife?invite=${encodeURIComponent(rawToken)}`, expiresAt });
  } catch (cause) {
    return apiError(cause, "Could not create household invitation.");
  }
}

export async function PUT(request: Request) {
  try {
    const { user } = await requireStorySession();
    const body = await request.json() as { token?: string };
    if (!body.token || !/^[A-Za-z0-9_-]{32,128}$/.test(body.token)) throw new Error("Invalid household invitation token.");
    const tokenHash = hashToken(body.token);
    const now = new Date().toISOString();
    const invite = (await supabaseAdminRest<InviteRow[]>(`household_invites?select=id,household_id,email,token_hash,can_add_memories,expires_at,accepted_at&token_hash=eq.${encodeURIComponent(tokenHash)}&accepted_at=is.null&expires_at=gt.${encodeURIComponent(now)}&limit=1`))[0];
    if (!invite || invite.accepted_at) throw new Error("This household invitation is invalid, expired, or has already been used.");
    if (new Date(invite.expires_at).getTime() <= Date.now()) throw new Error("This household invitation has expired.");
    if (!user.email || user.email.toLowerCase() !== invite.email.toLowerCase()) throw new Error("Sign in with the email address that received this invitation.");

    await supabaseAdminRest("household_memberships?on_conflict=household_id,user_id", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify({ household_id: invite.household_id, user_id: user.id, role: "member", can_add_memories: invite.can_add_memories }),
    });
    const claimed = await supabaseAdminRest<InviteRow[]>(`household_invites?id=eq.${encodeURIComponent(invite.id)}&accepted_at=is.null&select=id,household_id,email,token_hash,can_add_memories,expires_at,accepted_at`, {
      method: "PATCH",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify({ accepted_at: new Date().toISOString() }),
    });
    if (!claimed[0]) throw new Error("This household invitation has already been used.");
    return NextResponse.json({ accepted: true, householdId: invite.household_id });
  } catch (cause) {
    return apiError(cause, "Could not accept household invitation.");
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

type HouseholdRow = { id: string; owner_id: string };

function apiError(cause: unknown) {
  const message = cause instanceof Error ? cause.message : "Could not update household membership.";
  const status = message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : /owner|forbidden/i.test(message) ? 403 : 400;
  return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Sign in to manage household members." : message }, { status });
}

export async function DELETE(request: Request) {
  try {
    const { token, user } = await requireStorySession();
    const url = new URL(request.url);
    const householdId = url.searchParams.get("householdId");
    const userId = url.searchParams.get("userId");
    if (!householdId || !userId || !/^[0-9a-f-]{36}$/i.test(householdId) || !/^[0-9a-f-]{36}$/i.test(userId)) throw new Error("Invalid household member request.");
    if (userId === user.id) throw new Error("The household owner cannot remove their own owner membership.");
    const household = (await supabaseRest<HouseholdRow[]>(`households?select=id,owner_id&id=eq.${encodeURIComponent(householdId)}&owner_id=eq.${encodeURIComponent(user.id)}&limit=1`, token))[0];
    if (!household) throw new Error("Only the household owner can remove members.");
    await supabaseRest<null>(`household_memberships?household_id=eq.${encodeURIComponent(householdId)}&user_id=eq.${encodeURIComponent(userId)}`, token, { method: "DELETE" });
    return new NextResponse(null, { status: 204 });
  } catch (cause) {
    return apiError(cause);
  }
}

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

type PetRow = { id: string; household_id: string; name: string };
type HouseholdRow = { id: string; owner_id: string };
type MembershipRow = { household_id: string; user_id: string; role: "owner" | "member"; can_add_memories: boolean };

function errorResponse(cause: unknown) {
  const message = cause instanceof Error ? cause.message : "Could not add this shared memory.";
  const status = message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : /permission|access/i.test(message) ? 403 : 400;
  return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Sign in to add a shared PetLife memory." : message }, { status });
}

function uuid(value: string) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}

export async function POST(request: Request) {
  try {
    const { token, user } = await requireStorySession();
    const body = await request.json() as {
      petId?: string;
      type?: "memory" | "milestone";
      date?: string;
      title?: string;
      note?: string;
      photoCount?: number;
    };

    if (!body.petId || !uuid(body.petId)) throw new Error("Invalid shared pet id.");
    if (!body.type || !["memory", "milestone"].includes(body.type)) throw new Error("Unsupported pet memory type.");
    if (!body.date || !/^\d{4}-\d{2}-\d{2}$/.test(body.date)) throw new Error("Invalid pet memory date.");
    const title = body.title?.trim() ?? "";
    const note = body.note?.trim() ?? "";
    const photoCount = body.photoCount ?? 0;
    if (!title || title.length > 120) throw new Error("Pet memory title must be 1–120 characters.");
    if (note.length > 500) throw new Error("Pet memory note is too long.");
    if (!Number.isInteger(photoCount) || photoCount < 0 || photoCount > 12) throw new Error("Invalid photo count.");

    const pet = (await supabaseRest<PetRow[]>(`pets?select=id,household_id,name&id=eq.${encodeURIComponent(body.petId)}&limit=1`, token))[0];
    if (!pet) throw new Error("You do not have access to this shared pet.");

    const [ownedHousehold, membership] = await Promise.all([
      supabaseRest<HouseholdRow[]>(`households?select=id,owner_id&id=eq.${encodeURIComponent(pet.household_id)}&owner_id=eq.${encodeURIComponent(user.id)}&limit=1`, token),
      supabaseRest<MembershipRow[]>(`household_memberships?select=household_id,user_id,role,can_add_memories&household_id=eq.${encodeURIComponent(pet.household_id)}&user_id=eq.${encodeURIComponent(user.id)}&limit=1`, token),
    ]);
    const isOwner = Boolean(ownedHousehold[0]) || membership[0]?.role === "owner";
    const mayAdd = isOwner || Boolean(membership[0]?.can_add_memories);
    if (!mayAdd) throw new Error("Your household membership does not have permission to add memories.");

    const id = randomUUID();
    await supabaseRest("pet_memories?select=id", token, {
      method: "POST",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify({
        id,
        pet_id: pet.id,
        household_id: pet.household_id,
        created_by: user.id,
        memory_type: body.type,
        memory_date: body.date,
        title,
        note: note || null,
        photo_count: photoCount,
      }),
    });

    return NextResponse.json({ id, petId: pet.id, householdId: pet.household_id }, { status: 201 });
  } catch (cause) {
    return errorResponse(cause);
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { isSupabaseConfigured } from "@/platform/persistence/config";
import { supabaseRest } from "@/platform/persistence/supabase-rest";
import type { PetMemory, PetProfile } from "@/products/petlife/model";

export const runtime = "nodejs";

type HouseholdRow = { id: string; name: string; owner_id: string };
type MembershipRow = { household_id: string; user_id: string; email?: string | null; role: "owner" | "member"; can_add_memories: boolean };
type PetRow = { id: string; household_id: string; name: string; species: string; birthday?: string | null; adoption_date?: string | null };
type PetMemoryRow = { id: string; pet_id: string; household_id: string; created_by: string; memory_type: string; memory_date: string; title: string; note?: string | null; photo_count: number };

function apiError(cause: unknown, fallback: string) {
  const message = cause instanceof Error ? cause.message : fallback;
  const status = message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400;
  return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Sign in to use PetLife cloud features." : message }, { status });
}

function requirePetLifeCloud() {
  if (!isSupabaseConfigured()) throw new Error("Supabase persistence is not configured for PetLife.");
}

function assertUuid(value: string) {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)) throw new Error("Invalid PetLife id.");
}

function validateProfile(profile: PetProfile) {
  assertUuid(profile.id);
  if (!profile.name?.trim() || profile.name.trim().length > 80) throw new Error("Pet name must be 1–80 characters.");
  if (!profile.species?.trim() || profile.species.trim().length > 60) throw new Error("Pet species must be 1–60 characters.");
  if (profile.birthday && !/^\d{4}-\d{2}-\d{2}$/.test(profile.birthday)) throw new Error("Invalid birthday.");
  if (profile.adoptionDate && !/^\d{4}-\d{2}-\d{2}$/.test(profile.adoptionDate)) throw new Error("Invalid adoption date.");
}

function validateMemory(memory: PetMemory, petId: string) {
  assertUuid(memory.id);
  if (memory.petId !== petId) throw new Error("Memory pet id does not match the profile.");
  if (!["memory", "milestone"].includes(memory.type)) throw new Error("Unsupported pet memory type.");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(memory.date)) throw new Error("Invalid pet memory date.");
  if (!memory.title?.trim() || memory.title.trim().length > 120) throw new Error("Pet memory title must be 1–120 characters.");
  if (memory.note && memory.note.length > 500) throw new Error("Pet memory note is too long.");
  if (!Number.isInteger(memory.photoCount) || memory.photoCount < 0 || memory.photoCount > 12) throw new Error("Invalid photo count.");
}

export async function GET() {
  try {
    requirePetLifeCloud();
    const { token, user } = await requireStorySession();
    const [households, memberships, pets, memories] = await Promise.all([
      supabaseRest<HouseholdRow[]>("households?select=id,name,owner_id&order=created_at.asc", token),
      supabaseRest<MembershipRow[]>("household_memberships?select=household_id,user_id,email,role,can_add_memories", token),
      supabaseRest<PetRow[]>("pets?select=id,household_id,name,species,birthday,adoption_date&order=created_at.asc", token),
      supabaseRest<PetMemoryRow[]>("pet_memories?select=id,pet_id,household_id,created_by,memory_type,memory_date,title,note,photo_count&order=memory_date.desc&limit=250", token),
    ]);
    return NextResponse.json({ user: { id: user.id, email: user.email }, households, memberships, pets, memories });
  } catch (cause) {
    return apiError(cause, "Could not load PetLife cloud data.");
  }
}

export async function POST(request: Request) {
  try {
    requirePetLifeCloud();
    const { token, user } = await requireStorySession();
    const body = await request.json() as { profile?: PetProfile; memories?: PetMemory[] };
    if (!body.profile) throw new Error("Pet profile is required.");
    validateProfile(body.profile);
    const memories = body.memories ?? [];
    if (!Array.isArray(memories) || memories.length > 250) throw new Error("Too many pet memories in one sync.");
    memories.forEach((memory) => validateMemory(memory, body.profile!.id));

    let household = (await supabaseRest<HouseholdRow[]>(`households?select=id,name,owner_id&owner_id=eq.${encodeURIComponent(user.id)}&order=created_at.asc&limit=1`, token))[0];
    if (!household) {
      const created = await supabaseRest<HouseholdRow[]>("households?select=id,name,owner_id", token, {
        method: "POST",
        headers: { Prefer: "return=representation" },
        body: JSON.stringify({ owner_id: user.id, name: `${body.profile.name.trim()}'s household` }),
      });
      household = created[0];
      if (!household) throw new Error("Could not create PetLife household.");
      await supabaseRest<MembershipRow[]>("household_memberships?on_conflict=household_id,user_id", token, {
        method: "POST",
        headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
        body: JSON.stringify({ household_id: household.id, user_id: user.id, email: user.email ?? null, role: "owner", can_add_memories: true }),
      });
    }

    await supabaseRest<PetRow[]>("pets?on_conflict=id", token, {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify({ id: body.profile.id, household_id: household.id, name: body.profile.name.trim(), species: body.profile.species.trim(), birthday: body.profile.birthday ?? null, adoption_date: body.profile.adoptionDate ?? null }),
    });

    if (memories.length) {
      await supabaseRest<PetMemoryRow[]>("pet_memories?on_conflict=id", token, {
        method: "POST",
        headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
        body: JSON.stringify(memories.map((memory) => ({ id: memory.id, pet_id: body.profile!.id, household_id: household!.id, created_by: user.id, memory_type: memory.type, memory_date: memory.date, title: memory.title.trim(), note: memory.note?.trim() || null, photo_count: memory.photoCount }))),
      });
    }

    return NextResponse.json({ householdId: household.id, petId: body.profile.id, syncedMemories: memories.length });
  } catch (cause) {
    return apiError(cause, "Could not sync PetLife data.");
  }
}

export async function DELETE(request: Request) {
  try {
    requirePetLifeCloud();
    const { token } = await requireStorySession();
    const id = new URL(request.url).searchParams.get("id");
    if (!id) throw new Error("Pet id is required.");
    assertUuid(id);
    await supabaseRest<null>(`pets?id=eq.${encodeURIComponent(id)}`, token, { method: "DELETE" });
    return new NextResponse(null, { status: 204 });
  } catch (cause) {
    return apiError(cause, "Could not delete the cloud pet profile.");
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

type Profile = { user_id: string; display_name: string | null; avatar_media_id: string | null; timezone: string | null; locale: string | null; onboarding_completed: boolean; interests: string[] };

export async function GET() {
  try {
    const session = await requireStorySession();
    const rows = await supabaseRest<Profile[]>(`profiles?user_id=eq.${encodeURIComponent(session.user.id)}&select=user_id,display_name,avatar_media_id,timezone,locale,onboarding_completed,interests`, session.token);
    return NextResponse.json({ profile: rows[0] ?? null, user: { id: session.user.id, email: session.user.email ?? null } });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not load profile.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function PUT(request: Request) {
  try {
    const session = await requireStorySession();
    const body = await request.json() as { displayName?: string; timezone?: string; locale?: string; onboardingCompleted?: boolean; interests?: string[] };
    const displayName = body.displayName?.trim().slice(0, 80) || session.user.user_metadata?.display_name?.toString().slice(0, 80) || "Story keeper";
    const payload = {
      user_id: session.user.id,
      display_name: displayName,
      timezone: body.timezone?.slice(0, 80) || null,
      locale: body.locale?.slice(0, 24) || "en-US",
      onboarding_completed: Boolean(body.onboardingCompleted),
      interests: Array.isArray(body.interests) ? body.interests.filter((value) => typeof value === "string").slice(0, 10) : [],
      updated_at: new Date().toISOString(),
    };
    const rows = await supabaseRest<Profile[]>("profiles?on_conflict=user_id", session.token, { method: "POST", headers: { Prefer: "resolution=merge-duplicates,return=representation" }, body: JSON.stringify(payload) });
    return NextResponse.json({ profile: rows[0] ?? payload });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not update profile.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { isSupabaseConfigured } from "@/platform/persistence/config";
import { assertDerivedStoryPayload, supabaseRest } from "@/platform/persistence/supabase-rest";
import { isThreadTaleResultV2 } from "@/platform/threadtales/result-v2";

export const runtime = "nodejs";

function requireCloudPersistence() {
  if (!isSupabaseConfigured()) throw new Error("Supabase persistence is not configured.");
}

export async function GET() {
  try {
    requireCloudPersistence();
    const { token } = await requireStorySession();
    const rows = await supabaseRest<Array<{ id: string; product: string; mode?: string; title: string; result: unknown; created_at: string }>>(
      "story_runs?select=id,product,mode,title,result,created_at&order=created_at.desc&limit=25",
      token,
    );
    return NextResponse.json({ stories: rows });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not load saved stories.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Sign in to save and reopen stories." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function POST(request: Request) {
  try {
    requireCloudPersistence();
    const { token, user } = await requireStorySession();
    const body = await request.json() as { product?: string; mode?: string; title?: string; result?: unknown };
    if (!body.product || !["threadtales", "myyear", "petlife"].includes(body.product)) throw new Error("Unsupported story product.");
    if (!body.title || body.title.trim().length > 160) throw new Error("Give this story a title under 160 characters.");
    assertDerivedStoryPayload(body.result);
    if (body.product === "threadtales" && !isThreadTaleResultV2(body.result)) throw new Error("ThreadTales cloud saves require the derived result v2 schema.");

    const rows = await supabaseRest<Array<{ id: string; product: string; mode?: string; title: string; created_at: string }>>(
      "story_runs?select=id,product,mode,title,created_at",
      token,
      {
        method: "POST",
        headers: { Prefer: "return=representation" },
        body: JSON.stringify({
          user_id: user.id,
          product: body.product,
          mode: body.mode ?? null,
          title: body.title.trim(),
          result: body.result,
        }),
      },
    );
    return NextResponse.json({ story: rows[0] ?? null }, { status: 201 });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not save this story.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Sign in before saving." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function DELETE(request: Request) {
  try {
    requireCloudPersistence();
    const { token } = await requireStorySession();
    const id = new URL(request.url).searchParams.get("id");
    if (!id || !/^[0-9a-f-]{36}$/i.test(id)) throw new Error("Invalid story id.");
    await supabaseRest<null>(`story_runs?id=eq.${encodeURIComponent(id)}`, token, { method: "DELETE" });
    return new NextResponse(null, { status: 204 });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not delete this story.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Sign in before deleting." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { NextResponse } from "next/server";
import { verifyStripeWebhookSignature } from "@/platform/billing/stripe-rest";
import { fulfillVerifiedStripeWebhook } from "@/platform/entitlements/stripe-fulfillment";
import {
  hasProcessedStripeEvent,
  reconcileSubscriptionEvent,
  recordStripeEvent,
} from "@/platform/billing/stripe-subscriptions";

export const runtime = "nodejs";

type StripeEvent = {
  id?: string;
  type?: string;
  data?: { object?: Record<string, unknown> };
};

function isSubscriptionLifecycleEvent(event: StripeEvent) {
  if (event.type?.startsWith("customer.subscription.")) return true;
  if (event.type === "invoice.paid" || event.type === "invoice.payment_failed") return true;
  return event.type === "checkout.session.completed"
    && event.data?.object?.mode === "subscription";
}

export async function POST(request: Request) {
  const signature = request.headers.get("stripe-signature");
  if (!signature) {
    return NextResponse.json({ error: "Missing Stripe signature." }, { status: 400 });
  }

  const rawBody = await request.text();

  try {
    if (!verifyStripeWebhookSignature(rawBody, signature)) {
      return NextResponse.json({ error: "Invalid Stripe signature." }, { status: 400 });
    }
  } catch (cause) {
    const message =
      cause instanceof Error ? cause.message : "Webhook validation failed.";
    return NextResponse.json(
      { error: message },
      { status: /not configured/i.test(message) ? 503 : 400 },
    );
  }

  let event: StripeEvent;
  try {
    event = JSON.parse(rawBody) as StripeEvent;
  } catch {
    return NextResponse.json(
      { error: "Invalid Stripe event payload." },
      { status: 400 },
    );
  }

  if (
    !event.id
    || !event.type
    || !/^evt_[A-Za-z0-9_]+$/.test(event.id)
  ) {
    return NextResponse.json({ error: "Invalid Stripe event." }, { status: 400 });
  }

  /*
   * Legacy one-time ThreadTales checkout fulfillment is already idempotent at
   * its entitlement provider_reference and intentionally works when cloud
   * persistence is unavailable. Keep that contract independent from the
   * durable subscription event ledger.
   */
  if (!isSubscriptionLifecycleEvent(event)) {
    try {
      const entitlement = await fulfillVerifiedStripeWebhook(event);
      return NextResponse.json({
        received: true,
        id: event.id,
        type: event.type,
        ...entitlement,
        subscription: false,
      });
    } catch (cause) {
      const message =
        cause instanceof Error ? cause.message : "Stripe event persistence failed.";
      return NextResponse.json({ error: message }, { status: 502 });
    }
  }

  /*
   * Subscription events are state-changing and must be durably reconciled.
   * Any persistence/configuration failure remains retryable so Stripe can
   * redeliver after the underlying problem is fixed.
   */
  try {
    if (await hasProcessedStripeEvent(event.id)) {
      return NextResponse.json({
        received: true,
        replay: true,
        id: event.id,
        type: event.type,
      });
    }

    const entitlement = await fulfillVerifiedStripeWebhook(event);
    const subscription = await reconcileSubscriptionEvent(event);
    await recordStripeEvent(event.id, event.type);

    return NextResponse.json({
      received: true,
      id: event.id,
      type: event.type,
      entitlement,
      subscription,
    });
  } catch (cause) {
    const message =
      cause instanceof Error ? cause.message : "Stripe event persistence failed.";
    return NextResponse.json({ error: message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { isSupabaseServerConfigured } from "@/platform/persistence/config";
import { supabaseAdminRest } from "@/platform/persistence/supabase-rest";
import { sanitizeProductEvent } from "@/platform/telemetry/events";
import { deliverToPulseAtlas } from "@/platform/telemetry/pulseatlas";

export const runtime = "nodejs";

function telemetryEndpoint() {
  const raw = process.env.TELEMETRY_ENDPOINT;
  if (!raw) return null;
  const url = new URL(raw);
  if (url.protocol !== "https:") throw new Error("Telemetry endpoint must use HTTPS.");
  return url.toString();
}

async function deliverToSupabase(event: ReturnType<typeof sanitizeProductEvent>) {
  await supabaseAdminRest<null>("product_events", {
    method: "POST",
    headers: { Prefer: "return=minimal" },
    body: JSON.stringify({ event: event.event, product: event.product, mode: event.mode ?? null }),
  });
}

export async function POST(request: Request) {
  try {
    const event = sanitizeProductEvent(await request.json());
    // Independent fail-open fanout. PulseAtlas is deliberately invisible to the
    // existing telemetry API contract, and only receives the sanitized event.
    void deliverToPulseAtlas(event);
    const endpoint = telemetryEndpoint();

    if (endpoint) {
      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(process.env.TELEMETRY_API_KEY ? { Authorization: `Bearer ${process.env.TELEMETRY_API_KEY}` } : {}),
        },
        body: JSON.stringify({ ...event, occurredAt: new Date().toISOString() }),
        cache: "no-store",
      });
      if (!response.ok) throw new Error("Telemetry destination rejected the event.");
      return NextResponse.json({ accepted: true, delivered: true }, { status: 202 });
    }

    if (isSupabaseServerConfigured()) {
      await deliverToSupabase(event);
      return NextResponse.json({ accepted: true, delivered: true }, { status: 202 });
    }

    return NextResponse.json({ accepted: true, delivered: false }, { status: 202 });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Invalid telemetry event.";
    return NextResponse.json({ error: message }, { status: /invalid|unsupported/i.test(message) ? 400 : 502 });
  }
}

